function useQueryString(path: string) {
  const [location, setLocation] = useLocation();
  const params = useMemo(() => new URLSearchParams(location.split('?')[1] ?? ''), [location]);
  const update = (updates: Record<string, string | string[] | undefined>) => {
    const next = new URLSearchParams(params);
    Object.entries(updates).forEach(([key, value]) => {
      if (value === undefined || value === '' || (Array.isArray(value) && value.length === 0)) next.delete(key);
      else next.set(key, Array.isArray(value) ? value.join(',') : value);
    });
    setLocation(`${path}${next.toString() ? `?${next.toString()}` : ''}`);
  };
  return { location, params, update };
}

