function FilterSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) {
  return <label className="grid gap-1.5"><span className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">{label}</span><select value={value} onChange={(event) => onChange(event.target.value)} className="h-11 rounded-xl border border-border bg-card px-3 text-sm font-semibold outline-none focus:border-primary">{options.map((option) => <option key={option}>{option}</option>)}</select></label>;
}

function Jobs() {
  const { location, params, update } = useQueryString('/jobs');
  const [saved, setSaved] = usePersistentState<string[]>('workforge-saved-jobs', ['northstar']);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  useEffect(() => { setLoading(true); const timer = window.setTimeout(() => setLoading(false), 180); return () => window.clearTimeout(timer); }, [location]);

  const rawCategory = params.get('category') ?? 'All categories';
  const category = categoryAliases[rawCategory.toLowerCase()] ?? rawCategory;
  const search = params.get('q') ?? '';
  const selectedSkills = params.get('skills')?.split(',').filter(Boolean) ?? [];
  const budgetMin = params.get('budgetMin') ?? '';
  const budgetMax = params.get('budgetMax') ?? '';
  const experience = params.get('experience') ?? 'All experience';
  const jobType = params.get('jobType') ?? 'All job types';
  const locationFilter = params.get('location') ?? 'All locations';
  const availability = params.get('availability') ?? 'Any start date';
  const sort = params.get('sort') ?? 'newest';
  const page = Math.max(Number(params.get('page') ?? 1), 1);

  const filtered = useMemo(() => {
    const result = jobs.filter((job) => {
      const textMatch = `${job.title} ${job.company} ${job.tags.join(' ')} ${job.description}`.toLowerCase().includes(search.toLowerCase());
      const categoryMatch = category === 'All categories' || job.category === category;
      const skillsMatch = selectedSkills.length === 0 || selectedSkills.every((skill) => job.skills.includes(skill));
      const minMatch = !budgetMin || job.budgetMax >= Number(budgetMin);
      const maxMatch = !budgetMax || job.budgetMin <= Number(budgetMax);
      const experienceMatch = experience === 'All experience' || job.experience === experience;
      const typeMatch = jobType === 'All job types' || job.jobType === jobType;
      const locationMatch = locationFilter === 'All locations' || (locationFilter === 'Remote' ? job.remote : !job.remote);
      const availabilityMatch = availability === 'Any start date' || job.availability === availability;
      return textMatch && categoryMatch && skillsMatch && minMatch && maxMatch && experienceMatch && typeMatch && locationMatch && availabilityMatch;
    });
    return [...result].sort((a, b) => {
      if (sort === 'popular') return b.proposals - a.proposals;
      if (sort === 'budget-high') return b.budgetMax - a.budgetMax;
      if (sort === 'budget-low') return a.budgetMin - b.budgetMin;
      return Date.parse(b.postedAt) - Date.parse(a.postedAt);
    });
  }, [availability, budgetMax, budgetMin, category, experience, jobType, locationFilter, search, selectedSkills, sort]);
  const pageSize = 4;
  const pageCount = Math.max(Math.ceil(filtered.length / pageSize), 1);
  const visible = filtered.slice((Math.min(page, pageCount) - 1) * pageSize, Math.min(page, pageCount) * pageSize);
  const clearFilters = () => update({ q: undefined, category: undefined, skills: undefined, budgetMin: undefined, budgetMax: undefined, experience: undefined, jobType: undefined, location: undefined, availability: undefined, sort: undefined, page: undefined });
  const toggleSkill = (skill: string) => update({ skills: selectedSkills.includes(skill) ? selectedSkills.filter((item) => item !== skill) : [...selectedSkills, skill], page: '1' });

  return <Shell><main className="page-in mx-auto max-w-[1280px] px-5 py-10 lg:px-8 lg:py-14">
    <PageIntro eyebrow="Open opportunities" title="Find work worth doing." body="Thoughtful briefs from teams looking for independent talent." action={<Link href="/post-job" className="inline-flex min-h-10 items-center gap-2 self-start rounded-xl bg-secondary px-4 text-sm font-bold text-foreground transition hover:-translate-y-0.5 md:self-auto"><Plus size={17} /> Post a job</Link>} />
    <div className="mt-9 flex flex-col gap-3 md:flex-row"><div className="flex h-12 flex-1 items-center gap-3 rounded-xl border border-border bg-card px-4 shadow-soft"><Search size={18} className="text-muted-foreground" /><input value={search} onChange={(event) => update({ q: event.target.value, page: '1' })} placeholder="Search roles, skills, or companies" className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground" aria-label="Search jobs" /></div><button onClick={() => setFiltersOpen(!filtersOpen)} className="flex h-12 items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 text-sm font-semibold md:hidden" aria-expanded={filtersOpen}><SlidersHorizontal size={17} /> Filters {selectedSkills.length > 0 && <Badge tone="teal">{selectedSkills.length}</Badge>}</button><select value={sort} onChange={(event) => update({ sort: event.target.value, page: '1' })} className="h-12 rounded-xl border border-border bg-card px-4 text-sm font-semibold outline-none" aria-label="Sort jobs"><option value="newest">Newest first</option><option value="popular">Most proposals</option><option value="budget-high">Highest budget</option><option value="budget-low">Lowest budget</option></select></div>
    <div className={`${filtersOpen ? 'grid' : 'hidden'} mt-4 grid-cols-1 gap-4 rounded-2xl border border-border bg-card p-4 md:grid md:grid-cols-3 lg:grid-cols-5`}>
      <FilterSelect label="Category" value={category} onChange={(value) => update({ category: value === 'All categories' ? undefined : value, page: '1' })} options={['All categories', ...categories.map((item) => item.name)]} />
      <FilterSelect label="Experience" value={experience} onChange={(value) => update({ experience: value === 'All experience' ? undefined : value, page: '1' })} options={['All experience', 'Entry level', 'Mid-level', 'Senior']} />
      <FilterSelect label="Job type" value={jobType} onChange={(value) => update({ jobType: value === 'All job types' ? undefined : value, page: '1' })} options={['All job types', 'Project', 'Ongoing']} />
      <FilterSelect label="Location" value={locationFilter} onChange={(value) => update({ location: value === 'All locations' ? undefined : value, page: '1' })} options={['All locations', 'Remote', 'On-site']} />
      <FilterSelect label="Start date" value={availability} onChange={(value) => update({ availability: value === 'Any start date' ? undefined : value, page: '1' })} options={['Any start date', 'Start this month', 'Start next month']} />
      <FilterSelect label="Minimum budget" value={budgetMin} onChange={(value) => update({ budgetMin: value, page: '1' })} options={['', '1000', '2500', '5000', '7500']} />
      <FilterSelect label="Maximum budget" value={budgetMax} onChange={(value) => update({ budgetMax: value, page: '1' })} options={['', '5000', '7500', '10000', '25000']} />
      <div className="grid gap-2 md:col-span-2 lg:col-span-3"><span className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">Skills</span><div className="flex flex-wrap gap-1.5">{allSkills.slice(0, 10).map((skill) => <button key={skill} onClick={() => toggleSkill(skill)} className={`rounded-lg px-2.5 py-1.5 text-xs font-semibold transition ${selectedSkills.includes(skill) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:text-foreground'}`} aria-pressed={selectedSkills.includes(skill)}>{skill}</button>)}</div></div>
      <div className="flex items-end justify-end"><Button variant="quiet" onClick={clearFilters}>Clear filters</Button></div>
    </div>
    <div className="mt-9 grid gap-5 lg:grid-cols-[1fr_320px]"><div><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-semibold">{filtered.length} opportunities <span className="font-normal text-muted-foreground">matching your search</span></p><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Page {Math.min(page, pageCount)} of {pageCount}</span></div>{loading ? <LoadingState label="Loading opportunities" /> : visible.length ? <div className="grid gap-4">{visible.map((job) => <JobCard key={job.id} job={job} saved={saved.includes(job.id)} onSave={(id) => setSaved(saved.includes(id) ? saved.filter((item) => item !== id) : [...saved, id])} />)}</div> : <EmptyState title="No work found" body="Try a broader search or browse all categories." action="Clear filters" onClick={clearFilters} icon={<Compass size={21} />} />}<div className="mt-6 flex items-center justify-between"><Button variant="outline" disabled={page <= 1} onClick={() => update({ page: String(page - 1) })}><ArrowLeft size={15} /> Previous</Button><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">{filtered.length ? `${(Math.min(page, pageCount) - 1) * pageSize + 1}–${Math.min(page, pageCount) * pageSize > filtered.length ? filtered.length : Math.min(page, pageCount) * pageSize}` : '0'} results</span><Button variant="outline" disabled={page >= pageCount} onClick={() => update({ page: String(page + 1) })}>Next <ArrowRight size={15} /></Button></div></div><aside className="hidden h-fit rounded-2xl border border-border bg-card p-5 lg:block"><div className="flex items-center justify-between"><h2 className="font-display text-lg font-bold">Your saved work</h2><BookmarkIcon /></div><p className="mt-2 text-sm leading-6 text-muted-foreground">Keep promising projects close while you find the right fit.</p><div className="mt-6 grid gap-3">{jobs.filter((job) => saved.includes(job.id)).map((job) => <Link href={`/jobs/${job.id}`} key={job.id} className="group rounded-xl bg-muted/70 p-3"><p className="text-sm font-bold leading-5 group-hover:text-primary">{job.title}</p><p className="mt-1 text-xs text-muted-foreground">{job.company} · {job.budget}</p></Link>)}</div><Link href="/dashboard/freelancer" className="mt-5 flex items-center gap-2 text-xs font-bold text-primary">View your workspace <ArrowRight size={14} /></Link></aside></div>
  </main></Shell>;
}

function BookmarkIcon() { return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" className="size-[17px] text-secondary"><path d="M6 4.75A1.75 1.75 0 0 1 7.75 3h8.5A1.75 1.75 0 0 1 18 4.75V21l-6-3.5L6 21V4.75Z" strokeLinecap="round" strokeLinejoin="round" /></svg>; }

function ProposalModal({ job, onClose, onSubmitted }: { job: Job; onClose: () => void; onSubmitted: (proposal: Pick<Proposal, 'price' | 'timeline' | 'coverLetter' | 'milestones'>) => void }) {
  const [coverLetter, setCoverLetter] = useState('');
  const [price, setPrice] = useState('');
  const [timeline, setTimeline] = useState('6 weeks');
  const [milestones, setMilestones] = useState('Discovery and direction\nPrototype and refinement\nFinal handoff');
  const [portfolio, setPortfolio] = useState('maya-finance');
  const [attachment, setAttachment] = useState(false);
  const [error, setError] = useState('');
  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (coverLetter.trim().length < 40) return setError('Share at least a few thoughtful sentences so the client understands your approach.');
    if (!price || Number(price) <= 0) return setError('Add a proposed price to continue.');
    setError('');
    onSubmitted({ coverLetter: coverLetter.trim(), price: Number(price), timeline, milestones: milestones.split('\n').map((item) => item.trim()).filter(Boolean) });
  };
  return <Modal title={`Apply to ${job.title}`} onClose={onClose} wide><form onSubmit={submit} className="grid gap-5">
    <p className="text-sm leading-6 text-muted-foreground">A good proposal gives the client a clear sense of how you think, what you would do first, and what a successful finish looks like.</p>
    {error && <div className="flex items-start gap-2 rounded-xl bg-[#fff4f1] p-3 text-sm leading-6 text-[#99463c]" role="alert"><CircleAlert size={17} className="mt-1 shrink-0" />{error}</div>}
    <label className="grid gap-2"><span className="text-sm font-bold">Cover letter</span><textarea value={coverLetter} onChange={(event) => setCoverLetter(event.target.value)} rows={6} placeholder="Tell Northstar Labs what stood out to you and how you would approach the work..." className="resize-none rounded-xl border border-border bg-card p-4 text-sm leading-6 outline-none focus:border-primary" required /></label>
    <div className="grid gap-5 sm:grid-cols-2"><label className="grid gap-2"><span className="text-sm font-bold">Proposed price</span><input type="number" min="1" value={price} onChange={(event) => setPrice(event.target.value)} placeholder={job.budgetType === 'hourly' ? '95' : '5600'} className="h-11 rounded-xl border border-border bg-card px-3 text-sm outline-none focus:border-primary" required /><span className="text-xs text-muted-foreground">{job.budgetType === 'hourly' ? 'per hour' : 'fixed project price'}</span></label><label className="grid gap-2"><span className="text-sm font-bold">Estimated timeline</span><select value={timeline} onChange={(event) => setTimeline(event.target.value)} className="h-11 rounded-xl border border-border bg-card px-3 text-sm outline-none focus:border-primary"><option>4 weeks</option><option>6 weeks</option><option>8 weeks</option><option>10 weeks</option></select></label></div>
    <label className="grid gap-2"><span className="text-sm font-bold">Milestones</span><textarea value={milestones} onChange={(event) => setMilestones(event.target.value)} rows={4} className="resize-none rounded-xl border border-border bg-card p-3 text-sm leading-6 outline-none focus:border-primary" /><span className="text-xs text-muted-foreground">Use one milestone per line.</span></label>
    <div className="rounded-xl border border-border bg-muted/50 p-4"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-bold">Relevant portfolio work</p><p className="mt-1 text-xs text-muted-foreground">Select a piece that gives context to your proposal.</p></div><select value={portfolio} onChange={(event) => setPortfolio(event.target.value)} className="h-10 rounded-lg border border-border bg-card px-2 text-xs font-semibold outline-none"><option value="maya-finance">Finance product system</option><option value="maya-care">Care plan service</option><option value="jonas-ops">Operations dashboard</option></select></div><label className="mt-4 flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={attachment} onChange={(event) => setAttachment(event.target.checked)} className="size-4 accent-[#1f8c79]" /> Include a work sample attachment</label></div>
    <div className="flex flex-wrap justify-end gap-3"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit">Send proposal <ArrowRight size={16} /></Button></div>
  </form></Modal>;
}

function JobDetail() {
  const { id } = useParams<{ id: string }>();
  const job = jobs.find((item) => item.id === id);
  const [savedJobs, setSavedJobs] = usePersistentState<string[]>('workforge-saved-jobs', []);
  const [proposalOpen, setProposalOpen] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [reported, setReported] = useState(false);
  if (!job) return <NotFoundPage title="This opportunity took an unexpected detour." body="The project may have closed or the link may be out of date." />;
  const client = clients.find((item) => item.id === job.clientId) ?? clients[0];
  const saved = savedJobs.includes(job.id);
  return <Shell><main className="page-in mx-auto max-w-[1100px] px-5 py-10 lg:px-8 lg:py-14"><Link href="/jobs" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowLeft size={16} /> All opportunities</Link><div className="mt-8 grid gap-8 lg:grid-cols-[1fr_330px]"><div><div className="flex flex-wrap gap-2"><Badge tone="gold">{job.featured ? 'Featured opportunity' : job.type}</Badge><Badge tone="teal">{job.category}</Badge>{job.remote && <Badge tone="muted">Remote</Badge>}</div><h1 className="mt-5 max-w-[760px] font-display text-4xl font-bold leading-[1.02] tracking-[-.06em] md:text-6xl">{job.title}</h1><div className="mt-5 flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-muted-foreground"><Link href={`/clients/${client.id}`} className="flex items-center gap-2 font-semibold text-foreground hover:text-primary"><span className={`grid size-8 place-items-center rounded-lg ${client.accent} font-display text-xs`}>{client.initials}</span>{job.company}</Link><span className="flex items-center gap-1.5"><MapPin size={15} /> {job.location}</span><span className="flex items-center gap-1.5"><Clock3 size={15} /> Posted {job.posted}</span></div><div className="mt-10 border-t border-border pt-8"><h2 className="font-display text-xl font-bold">About the project</h2><p className="mt-4 max-w-[700px] text-[16px] leading-8 text-muted-foreground">{job.description} We value clear thinking, thoughtful craft, and a collaborative process. You’ll have the space to make meaningful recommendations, not just execute a checklist.</p><h2 className="mt-10 font-display text-xl font-bold">What you’ll bring</h2><ul className="mt-4 grid gap-3 text-sm leading-6 text-muted-foreground">{['A strong point of view and the ability to explain your decisions', 'A portfolio showing relevant, shipped work', 'Comfort working asynchronously with a small, focused team', 'Care for the details that make an experience feel finished'].map((item) => <li key={item} className="flex gap-3"><Check size={17} className="mt-1 shrink-0 text-primary" />{item}</li>)}</ul><h2 className="mt-10 font-display text-xl font-bold">Skills and details</h2><div className="mt-4 flex flex-wrap gap-2">{job.skills.map((skill) => <Badge key={skill}>{skill}</Badge>)}</div><div className="mt-7 grid gap-4 sm:grid-cols-2"><InfoRow label="Experience" value={job.experience} /><InfoRow label="Timeline" value={job.timeline} /><InfoRow label="Engagement" value={job.jobType} /><InfoRow label="Availability" value={job.availability} /></div></div></div><aside className="h-fit rounded-2xl border border-border bg-card p-5 shadow-soft lg:sticky lg:top-24"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Project budget</p><p className="mt-2 font-display text-2xl font-bold">{job.budget}</p><p className="mt-2 text-xs text-muted-foreground">{job.proposals} proposals so far · {job.timeline}</p><div className="mt-6 grid gap-3"><Button onClick={() => setProposalOpen(true)} className="w-full">{submitted ? <><Check size={17} /> Proposal submitted</> : <>Build a proposal <ArrowRight size={17} /></>}</Button><Button onClick={() => setSavedJobs(saved ? savedJobs.filter((item) => item !== job.id) : [...savedJobs, job.id])} variant="outline" className="w-full"><BookmarkSmall /> {saved ? 'Saved to your list' : 'Save for later'}</Button></div>{submitted && <Notice>Proposal saved locally. The client-facing review flow is ready in the client workspace.</Notice>}<div className="mt-7 border-t border-border pt-5"><p className="text-xs font-semibold">About the client</p><Link href={`/clients/${client.id}`} className="mt-3 flex items-center gap-3"><span className={`grid size-10 place-items-center rounded-xl ${client.accent} font-display font-bold`}>{client.initials}</span><div><p className="text-sm font-bold">{client.name}</p><p className="text-xs text-muted-foreground">Member since {client.memberSince} · {client.completedProjects} projects</p></div></Link><div className="mt-4 flex flex-wrap items-center gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-1"><Star size={13} className="fill-secondary text-secondary" /> {client.rating} client rating</span>{client.verified && <span className="flex items-center gap-1 text-primary"><ShieldCheck size={13} /> Verified</span>}</div><button onClick={() => setReported(true)} className="mt-5 text-xs font-semibold text-muted-foreground underline decoration-border underline-offset-4 hover:text-accent">Report this opportunity</button>{reported && <p className="mt-3 rounded-lg bg-[#f3d9d3] p-3 text-xs leading-5 text-[#99463c]" role="status">Thanks. This frontend prototype has recorded your report locally for review.</p>}</div></aside></div></main>{proposalOpen && <ProposalModal job={job} onClose={() => setProposalOpen(false)} onSubmitted={(proposal) => { setSubmitted(true); setProposalOpen(false); window.localStorage.setItem(`workforge-proposal-${job.id}`, JSON.stringify(proposal)); }} />}</Shell>;
}

function BookmarkSmall() { return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" className="size-4"><path d="M6 4.75A1.75 1.75 0 0 1 7.75 3h8.5A1.75 1.75 0 0 1 18 4.75V21l-6-3.5L6 21V4.75Z" strokeLinecap="round" strokeLinejoin="round" /></svg>; }
function InfoRow({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-muted/60 p-4"><p className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">{label}</p><p className="mt-2 text-sm font-bold">{value}</p></div>; }

function Freelancers() {
  const { location, params, update } = useQueryString('/freelancers');
  const [saved, setSaved] = usePersistentState<string[]>('workforge-saved-talent', ['maya']);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  useEffect(() => { setLoading(true); const timer = window.setTimeout(() => setLoading(false), 180); return () => window.clearTimeout(timer); }, [location]);
  const search = params.get('q') ?? '';
  const selectedSkills = params.get('skills')?.split(',').filter(Boolean) ?? [];
  const availability = params.get('availability') ?? 'All availability';
  const rateMax = params.get('rateMax') ?? '';
  const rating = params.get('rating') ?? 'Any rating';
  const experience = params.get('experience') ?? 'All experience';
  const locationFilter = params.get('location') ?? 'All locations';
  const language = params.get('language') ?? 'All languages';
  const sort = params.get('sort') ?? 'recommended';
  const visible = useMemo(() => freelancers.filter((person) => {
    const textMatch = `${person.name} ${person.role} ${person.skills.join(' ')} ${person.bio}`.toLowerCase().includes(search.toLowerCase());
    const skillsMatch = selectedSkills.length === 0 || selectedSkills.every((skill) => person.skills.includes(skill));
    const availabilityMatch = availability === 'All availability' || (availability === 'Available now' ? person.availabilityKey === 'now' : person.availabilityKey !== 'now');
    const rateMatch = !rateMax || person.hourlyRate <= Number(rateMax);
    const ratingMatch = rating === 'Any rating' || person.rating >= Number(rating);
    const experienceMatch = experience === 'All experience' || person.experience === experience;
    const locationMatch = locationFilter === 'All locations' || (locationFilter === 'Remote-friendly' ? true : person.location.includes(locationFilter));
    const languageMatch = language === 'All languages' || person.languages.includes(language);
    return textMatch && skillsMatch && availabilityMatch && rateMatch && ratingMatch && experienceMatch && locationMatch && languageMatch;
  }).sort((a, b) => sort === 'rating' ? b.rating - a.rating : sort === 'rate-low' ? a.hourlyRate - b.hourlyRate : b.projects - a.projects), [availability, experience, language, locationFilter, rateMax, rating, search, selectedSkills, sort]);
  const clearFilters = () => update({ q: undefined, skills: undefined, availability: undefined, rateMax: undefined, rating: undefined, experience: undefined, location: undefined, language: undefined, sort: undefined });
  const toggleSkill = (skill: string) => update({ skills: selectedSkills.includes(skill) ? selectedSkills.filter((item) => item !== skill) : [...selectedSkills, skill] });
  return <Shell><main className="page-in mx-auto max-w-[1280px] px-5 py-10 lg:px-8 lg:py-14"><PageIntro eyebrow="The independent directory" title={<>Find your next<br /><span className="text-primary">great collaborator.</span></>} body="People with the skills, taste, and care to move your work forward." action={<div className="flex items-center gap-2 rounded-xl bg-[#f5e6bf] px-4 py-3 text-xs font-semibold text-[#765a19]"><ShieldCheck size={17} /> Every profile is identity checked</div>} /><div className="mt-9 flex flex-col gap-3 sm:flex-row"><div className="flex h-12 flex-1 items-center gap-3 rounded-xl border border-border bg-card px-4 shadow-soft"><Search size={18} className="text-muted-foreground" /><input value={search} onChange={(event) => update({ q: event.target.value })} placeholder="Search by skill, name, or specialty" className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground" aria-label="Search freelancers" /></div><button onClick={() => setFiltersOpen(!filtersOpen)} className="flex h-12 items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 text-sm font-semibold md:hidden" aria-expanded={filtersOpen}><SlidersHorizontal size={17} /> Filters</button><select value={sort} onChange={(event) => update({ sort: event.target.value })} className="h-12 rounded-xl border border-border bg-card px-4 text-sm font-semibold outline-none" aria-label="Sort freelancers"><option value="recommended">Recommended</option><option value="rating">Highest rated</option><option value="rate-low">Lowest rate</option></select></div><div className={`${filtersOpen ? 'grid' : 'hidden'} mt-4 grid-cols-1 gap-4 rounded-2xl border border-border bg-card p-4 md:grid md:grid-cols-3 lg:grid-cols-4`}><FilterSelect label="Availability" value={availability} onChange={(value) => update({ availability: value === 'All availability' ? undefined : value })} options={['All availability', 'Available now', 'Available later']} /><FilterSelect label="Rate" value={rateMax} onChange={(value) => update({ rateMax: value })} options={['', '75', '90', '110', '150']} /><FilterSelect label="Rating" value={rating} onChange={(value) => update({ rating: value === 'Any rating' ? undefined : value })} options={['Any rating', '4.5', '4.8', '4.9']} /><FilterSelect label="Experience" value={experience} onChange={(value) => update({ experience: value === 'All experience' ? undefined : value })} options={['All experience', '5+ years', '6+ years', '7+ years', '8+ years', '9+ years', '10+ years']} /><FilterSelect label="Location" value={locationFilter} onChange={(value) => update({ location: value === 'All locations' ? undefined : value })} options={['All locations', 'Remote-friendly', 'Brooklyn', 'Berlin', 'London', 'Austin']} /><FilterSelect label="Language" value={language} onChange={(value) => update({ language: value === 'All languages' ? undefined : value })} options={['All languages', 'English', 'German', 'French', 'Spanish', 'Mandarin']} /><div className="grid gap-2 md:col-span-2"><span className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">Skills</span><div className="flex flex-wrap gap-1.5">{allSkills.slice(0, 10).map((skill) => <button key={skill} onClick={() => toggleSkill(skill)} className={`rounded-lg px-2.5 py-1.5 text-xs font-semibold ${selectedSkills.includes(skill) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:text-foreground'}`} aria-pressed={selectedSkills.includes(skill)}>{skill}</button>)}</div></div><div className="flex items-end justify-end"><Button variant="quiet" onClick={clearFilters}>Clear filters</Button></div></div><div className="mt-10 flex items-center justify-between"><p className="text-sm font-semibold">{visible.length} people <span className="font-normal text-muted-foreground">ready to make something good</span></p><button onClick={() => setFiltersOpen(!filtersOpen)} className="hidden items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary md:flex"><Filter size={16} /> More filters</button></div><div className="mt-5">{loading ? <LoadingState label="Loading talent" /> : visible.length ? <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{visible.map((person) => <TalentCard key={person.id} person={person} saved={saved.includes(person.id)} onSave={(id) => setSaved(saved.includes(id) ? saved.filter((item) => item !== id) : [...saved, id])} />)}</div> : <EmptyState title="No one by that description yet" body="Try a different skill or remove one of the filters." action="Clear filters" onClick={clearFilters} icon={<UsersRound size={21} />} />}</div></main></Shell>;
}

function FreelancerProfile() {
  const { id } = useParams<{ id: string }>();
  const person = freelancers.find((item) => item.id === id);
  const [saved, setSaved] = usePersistentState<string[]>('workforge-saved-talent', []);
  const [notice, setNotice] = useState('');
  const [inviteOpen, setInviteOpen] = useState(false);
  if (!person) return <NotFoundPage title="This profile took an unexpected detour." body="The independent professional may have moved on, or the profile link may be out of date." />;
  return <Shell><main className="page-in mx-auto max-w-[1120px] px-5 py-10 lg:px-8 lg:py-14"><Link href="/freelancers" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowLeft size={16} /> All talent</Link><div className="mt-8 grid gap-9 lg:grid-cols-[1fr_320px]"><div><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><Avatar person={person} size="lg" /><div><div className="flex flex-wrap items-center gap-2"><h1 className="font-display text-4xl font-bold tracking-[-.06em]">{person.name}</h1>{person.verified && <Badge tone="teal"><ShieldCheck size={12} /> Verified</Badge>}</div><p className="mt-2 text-lg text-muted-foreground">{person.role}</p><p className="mt-2 flex flex-wrap items-center gap-2 text-sm text-muted-foreground"><MapPin size={14} /> {person.location} <span className="text-border">·</span> {person.timezone} <span className="text-border">·</span> <span className="text-primary">{person.availability}</span></p></div></div>{notice && <div className="mt-6"><Notice onClose={() => setNotice('')}>{notice}</Notice></div>}<div className="mt-10 border-y border-border py-7"><div className="grid grid-cols-2 gap-5 sm:grid-cols-4"><Stat label="Projects completed" value={String(person.projects)} /><Stat label="Client rating" value={person.rating.toFixed(2)} icon={<Star size={15} className="fill-secondary text-secondary" />} /><Stat label="Typical rate" value={person.rate} /><Stat label="Response time" value={person.responseTime.replace('Usually replies ', '')} /></div></div><section className="mt-9"><h2 className="font-display text-xl font-bold">A little about how I work</h2><p className="mt-4 max-w-[700px] text-[16px] leading-8 text-muted-foreground">{person.bio}</p></section><section className="mt-10"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Selected work</h2><Badge tone="muted">{person.portfolio.length} projects</Badge></div><div className="mt-4 grid gap-4 sm:grid-cols-2">{person.portfolio.map((item) => <div key={item.id} className="overflow-hidden rounded-2xl border border-border bg-card"><div className={`grid min-h-40 place-items-center bg-gradient-to-br ${item.tone} p-6`}><span className="font-display text-center text-2xl font-bold tracking-[-.05em] text-[#23303c]">{item.title}</span></div><div className="p-5"><p className="font-mono text-[10px] uppercase tracking-[.12em] text-primary">{item.category} · {item.client}</p><p className="mt-3 text-sm leading-6 text-muted-foreground">{item.description}</p></div></div>)}</div></section><section className="mt-10"><h2 className="font-display text-xl font-bold">Skills and languages</h2><div className="mt-4 flex flex-wrap gap-2">{person.skills.map((skill) => <Badge key={skill}>{skill}</Badge>)}</div><p className="mt-4 text-sm text-muted-foreground"><b className="text-foreground">Languages:</b> {person.languages.join(' · ')}</p></section><section className="mt-10"><h2 className="font-display text-xl font-bold">Work history</h2><div className="mt-4 grid gap-4">{person.workHistory.map((item) => <div key={`${item.company}-${item.title}`} className="border-l-2 border-primary pl-5"><div className="flex flex-wrap justify-between gap-2"><div><h3 className="font-bold">{item.title}</h3><p className="mt-1 text-sm text-muted-foreground">{item.company}</p></div><span className="font-mono text-[10px] text-muted-foreground">{item.period}</span></div><p className="mt-2 text-sm leading-6 text-muted-foreground">{item.description}</p></div>)}</div></section><section className="mt-10"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">What clients are saying</h2><Stars rating={person.rating.toFixed(2)} /></div><div className="mt-4 grid gap-4 md:grid-cols-2">{[['Maya gets to the heart of a problem quickly, then makes the solution feel obvious. A rare combination.', 'Priya S. · Northstar Labs'], ['Excellent partner from first workshop to final handoff. The work made our whole team better.', 'Tom R. · Cedar & Co.']].map(([quote, author]) => <div className="rounded-2xl bg-card p-5 shadow-soft" key={author}><span className="font-display text-4xl leading-none text-secondary">“</span><p className="mt-2 text-sm leading-6">{quote}</p><p className="mt-4 text-xs font-semibold text-muted-foreground">{author}</p></div>)}</div></section></div><aside className="h-fit rounded-2xl border border-border bg-card p-5 shadow-soft lg:sticky lg:top-24"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Let’s make a start</p><h2 className="mt-3 font-display text-2xl font-bold tracking-[-.04em]">Have a project in mind?</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Share a little context and {person.name.split(' ')[0]} will get back to you.</p><div className="mt-6 grid gap-3"><Button onClick={() => setNotice(`A conversation with ${person.name} is ready in your local inbox.`)} className="w-full">Start a conversation <Send size={16} /></Button><Button onClick={() => setSaved(saved.includes(person.id) ? saved.filter((item) => item !== person.id) : [...saved, person.id])} variant="outline" className="w-full"><Heart size={16} className={saved.includes(person.id) ? 'fill-current text-secondary' : ''} /> {saved.includes(person.id) ? 'Profile saved' : 'Save profile'}</Button><Button onClick={() => setInviteOpen(true)} variant="coral" className="w-full">Invite to a job <BriefcaseBusiness size={16} /></Button></div>{inviteOpen && <div className="mt-5 rounded-xl bg-[#f5e6bf] p-4 text-xs leading-5 text-[#765a19]" role="status"><b>Choose a project to invite {person.name.split(' ')[0]} to.</b><select className="mt-3 h-10 w-full rounded-lg border border-[#d8c798] bg-[#fff9e9] px-2 text-xs outline-none"><option>Product designer for a calmer finance app</option><option>Brand refresh for an independent hotel group</option></select><button onClick={() => { setInviteOpen(false); setNotice(`Invite sent to ${person.name}.`); }} className="mt-3 font-bold underline underline-offset-4">Send invite</button></div>}<div className="mt-7 border-t border-border pt-5 text-xs leading-6 text-muted-foreground"><p className="flex items-center gap-2 text-primary"><ShieldCheck size={14} /> Identity verified</p><p className="mt-2">Profile and selected work reviewed by the WorkForge community.</p></div></aside></div></main></Shell>;
}

function Stat({ label, value, icon }: { label: string; value: string; icon?: ReactNode }) { return <div><p className="flex items-center gap-1 font-display text-xl font-bold sm:text-2xl">{value} {icon}</p><p className="mt-1 text-xs leading-4 text-muted-foreground">{label}</p></div>; }

function ClientProfile() {
  const { id } = useParams<{ id: string }>();
  const client = clients.find((item) => item.id === id);
  if (!client) return <NotFoundPage title="This client profile took an unexpected detour." body="We could not find the company behind this link." />;
  const clientJobs = jobs.filter((job) => job.clientId === client.id);
  return <Shell><main className="page-in mx-auto max-w-[1080px] px-5 py-10 lg:px-8 lg:py-14"><Link href="/jobs" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowLeft size={16} /> Back to discovery</Link><div className="mt-8 grid gap-9 lg:grid-cols-[1fr_310px]"><div><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><span className={`grid size-24 place-items-center rounded-[26px] ${client.accent} font-display text-3xl font-bold`}>{client.initials}</span><div><div className="flex flex-wrap items-center gap-2"><h1 className="font-display text-4xl font-bold tracking-[-.06em]">{client.name}</h1>{client.verified && <Badge tone="teal"><ShieldCheck size={12} /> Verified client</Badge>}</div><p className="mt-2 flex flex-wrap items-center gap-2 text-sm text-muted-foreground"><MapPin size={14} /> {client.location} <span className="text-border">·</span> {client.timezone}</p></div></div><section className="mt-10"><h2 className="font-display text-xl font-bold">About {client.name}</h2><p className="mt-4 max-w-[700px] text-[16px] leading-8 text-muted-foreground">{client.description}</p></section><div className="mt-9 grid grid-cols-2 gap-4 sm:grid-cols-4"><Stat label="Client rating" value={client.rating.toFixed(2)} icon={<Star size={15} className="fill-secondary text-secondary" />} /><Stat label="Projects completed" value={String(client.completedProjects)} /><Stat label="Response rate" value={client.responseRate} /><Stat label="Typical budget" value={client.typicalBudget} /></div><section className="mt-10"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Jobs posted</h2><Badge tone="muted">{client.jobsPosted} total</Badge></div><div className="mt-4 grid gap-3">{clientJobs.length ? clientJobs.map((job) => <Link href={`/jobs/${job.id}`} key={job.id} className="group rounded-2xl border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-soft"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-display font-bold group-hover:text-primary">{job.title}</h3><p className="mt-1 text-sm text-muted-foreground">{job.budget} · {job.timeline}</p></div><ArrowUpRight size={17} className="text-muted-foreground group-hover:text-primary" /></div></Link>) : <EmptyState title="No public jobs yet" body="This client is building their next brief." />}</div></section><section className="mt-10"><h2 className="font-display text-xl font-bold">What freelancers say</h2><div className="mt-4 grid gap-4 md:grid-cols-2">{client.reviewsFromFreelancers.map((review) => <div key={review.author} className="rounded-2xl bg-card p-5 shadow-soft"><span className="font-display text-4xl leading-none text-secondary">“</span><p className="mt-2 text-sm leading-6">{review.quote}</p><p className="mt-4 text-xs font-semibold text-muted-foreground">{review.author}</p></div>)}</div></section></div><aside className="h-fit rounded-2xl border border-border bg-card p-5 shadow-soft lg:sticky lg:top-24"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Trust travels both ways</p><div className="mt-4 grid gap-4">{[['Member since', client.memberSince], ['Hiring history', client.hiringHistory], ['Active jobs', String(client.activeJobs)], ['Completed projects', String(client.completedProjects)]].map(([label, value]) => <div key={label} className="border-b border-border pb-4 last:border-b-0 last:pb-0"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-sm font-bold">{value}</p></div>)}</div><Link href={`/jobs?category=all&client=${client.id}`} className="mt-6 flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground">See open jobs <ArrowRight size={16} /></Link></aside></div></main></Shell>;
}

function Dashboard({ role = 'freelancer' }: { role?: 'freelancer' | 'client' }) {
  const [activeRole, setActiveRole] = useState(role);
  const [proposalStatuses, setProposalStatuses] = useState<Record<string, Proposal['status']>>(() => Object.fromEntries(proposals.map((proposal) => [proposal.id, proposal.status])));
  const freelancer = activeRole === 'freelancer';
  const metrics = freelancer ? [['Active proposals', '6', '+2 this week'], ['Profile views', '184', '+18% vs last week'], ['In progress', '2', 'On track'], ['This month', '$4,280', '+$820 pending']] : [['Open roles', '4', '2 new today'], ['Shortlisted', '12', 'Across 4 roles'], ['In progress', '3', 'All on track'], ['Spent this month', '$8,640', 'Within budget']];
  const activeProposals = proposals.filter((proposal) => proposalStatuses[proposal.id] !== 'Rejected');
  return <Shell><main className="page-in mx-auto max-w-[1280px] px-5 py-10 lg:px-8 lg:py-14"><PageIntro eyebrow="Your workspace" title="Good morning, Muhammad Emmaduddin." body={freelancer ? 'A clear view of the work moving forward.' : 'A clear view of the teams and work you are shaping.'} action={<div className="flex w-fit rounded-xl border border-border bg-card p-1"><button onClick={() => setActiveRole('freelancer')} className={`rounded-lg px-3 py-2 text-xs font-bold ${freelancer ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'}`} aria-pressed={freelancer}>Independent</button><button onClick={() => setActiveRole('client')} className={`rounded-lg px-3 py-2 text-xs font-bold ${!freelancer ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'}`} aria-pressed={!freelancer}>Client</button></div>} /><div className="mt-9 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{metrics.map(([label, value, note]) => <div key={label} className="rounded-2xl border border-border bg-card p-5"><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mt-3 font-display text-3xl font-bold tracking-[-.05em]">{value}</p><p className={`mt-2 font-mono text-[10px] ${note.includes('+') ? 'text-primary' : 'text-muted-foreground'}`}>{note}</p></div>)}</div><div className="mt-8 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-border bg-card p-5 md:p-7"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">{freelancer ? 'Keep moving' : 'Your active work'}</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em]">{freelancer ? 'Projects in motion' : 'Projects you are shaping'}</h2></div><button className="focus-ring grid size-9 place-items-center rounded-lg text-muted-foreground hover:bg-muted" aria-label="More workspace actions"><MoreHorizontal size={19} /></button></div><div className="mt-6 grid gap-3">{(freelancer ? [{ title: 'Product designer for a calmer finance app', company: 'Northstar Labs', status: 'Proposal viewed', progress: '65%' }, { title: 'Brand refresh for an independent hotel group', company: 'Morrow House', status: 'In discovery', progress: '32%' }, { title: 'Lifecycle email strategy', company: 'Orbit Health', status: 'Complete', progress: '100%' }] : [{ title: 'Q3 product experience', company: 'Maya Chen', status: 'In progress', progress: '72%' }, { title: 'B2B dashboard build', company: 'Ledgerline team', status: 'Shortlisting', progress: '42%' }, { title: 'Brand refresh', company: 'Rafael Torres', status: 'In review', progress: '86%' }]).map((item) => <div className="rounded-xl border border-border p-4 transition hover:border-primary/50" key={item.title}><div className="flex items-start justify-between gap-3"><div><h3 className="text-sm font-bold">{item.title}</h3><p className="mt-1 text-xs text-muted-foreground">{item.company}</p></div><Badge tone={item.status === 'Complete' ? 'teal' : 'gold'}>{item.status}</Badge></div><div className="mt-4 flex items-center gap-3"><div className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: item.progress }} /></div><span className="font-mono text-[10px] text-muted-foreground">{item.progress}</span></div></div>)}</div></section><aside className="grid gap-5"><div className="rounded-2xl bg-[#23303c] p-6 text-[#f1eadf]"><div className="flex items-center justify-between"><span className="grid size-9 place-items-center rounded-xl bg-secondary text-foreground"><Zap size={17} /></span><span className="font-mono text-[10px] uppercase tracking-widest text-[#9db2aa]">Your pulse</span></div><p className="mt-7 font-display text-2xl font-bold tracking-[-.04em]">You’re building a strong week.</p><p className="mt-3 text-sm leading-6 text-[#aebdb7]">{freelancer ? 'Your response time is in the top 12% of independent professionals in your category.' : 'Your project briefs get 2.4× more qualified responses than average.'}</p><Link href="/notifications" className="mt-6 flex items-center gap-2 text-xs font-semibold text-secondary"><ArrowUpRight size={15} /> See your notifications</Link></div><div className="rounded-2xl border border-border bg-card p-5"><div className="flex items-center justify-between"><h2 className="font-display font-bold">Next on your desk</h2><Clock3 size={17} className="text-muted-foreground" /></div><div className="mt-4 grid gap-3 text-sm"><Link href="/messages" className="flex items-center gap-3 hover:text-primary"><span className="grid size-8 place-items-center rounded-lg bg-[#f3d9d3] text-accent"><MessageCircle size={15} /></span><span><b>Reply to Maya</b><span className="block text-xs text-muted-foreground">Due today</span></span></Link><Link href={freelancer ? '/jobs' : '/dashboard/client'} className="flex items-center gap-3 hover:text-primary"><span className="grid size-8 place-items-center rounded-lg bg-[#f5e6bf] text-[#765a19]"><BriefcaseBusiness size={15} /></span><span><b>{freelancer ? 'Review saved jobs' : 'Review 3 proposals'}</b><span className="block text-xs text-muted-foreground">When you have a minute</span></span></Link></div></div></aside></div>{!freelancer && <section className="mt-5 rounded-2xl border border-border bg-card p-5 md:p-7"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">Hiring room</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em]">Compare proposals for Northstar Labs</h2><p className="mt-2 text-sm text-muted-foreground">Shortlist the people who feel right, then start a conversation before you hire.</p></div><Badge tone="gold">{activeProposals.length} active proposals</Badge></div><div className="mt-6 grid gap-4 lg:grid-cols-2">{activeProposals.map((proposal) => <ProposalCard key={proposal.id} proposal={proposal} status={proposalStatuses[proposal.id]} onStatus={(status) => setProposalStatuses((current) => ({ ...current, [proposal.id]: status }))} />)}</div></section>}</main></Shell>;
}

function ProposalCard({ proposal, status, onStatus }: { proposal: Proposal; status: Proposal['status']; onStatus: (status: Proposal['status']) => void }) {
  const person = freelancers.find((item) => item.id === proposal.freelancerId) ?? freelancers[0];
  return <article className="rounded-2xl border border-border bg-background p-5"><div className="flex items-start justify-between gap-3"><Link href={`/freelancers/${person.id}`} className="flex items-center gap-3"><Avatar person={person} size="sm" /><div><p className="font-bold hover:text-primary">{person.name}</p><p className="text-xs text-muted-foreground">{person.role}</p></div></Link><Badge tone={status === 'Shortlisted' ? 'gold' : status === 'Hired' ? 'teal' : 'muted'}>{status}</Badge></div><p className="mt-5 text-sm leading-6 text-muted-foreground">{proposal.coverLetter}</p><div className="mt-4 grid grid-cols-2 gap-3"><InfoRow label="Proposed price" value={`$${proposal.price.toLocaleString()}`} /><InfoRow label="Timeline" value={proposal.timeline} /></div><div className="mt-5 flex flex-wrap gap-2"><Button variant="outline" onClick={() => onStatus(status === 'Shortlisted' ? 'New' : 'Shortlisted')}><Star size={15} /> {status === 'Shortlisted' ? 'Remove shortlist' : 'Shortlist'}</Button><Button variant="quiet" onClick={() => onStatus('Rejected')}>Pass</Button><Button onClick={() => onStatus('Hired')}>{status === 'Hired' ? <><Check size={15} /> Hired</> : <>Hire <ArrowRight size={15} /></>}</Button></div></article>;
}

function Messages() {
  const [selectedId, setSelectedId] = useState(conversations[0].id);
  const [messagesByConversation, setMessagesByConversation] = useState<Record<string, string[]>>({});
  const [message, setMessage] = useState('');
  const [attachment, setAttachment] = useState(false);
  const [optionsOpen, setOptionsOpen] = useState(false);
  const [newMessageOpen, setNewMessageOpen] = useState(false);
  const [newRecipient, setNewRecipient] = useState('');
  const selected = conversations.find((conversation) => conversation.id === selectedId) ?? conversations[0];
  const sendMessage = (event: FormEvent) => { event.preventDefault(); if (!message.trim()) return; setMessagesByConversation((current) => ({ ...current, [selected.id]: [...(current[selected.id] ?? []), message.trim()] })); setMessage(''); };
  const startConversation = (event: FormEvent) => { event.preventDefault(); if (!newRecipient.trim()) return; setNewMessageOpen(false); setNewRecipient(''); setOptionsOpen(false); };
  return <Shell><main className="page-in mx-auto max-w-[1280px] px-5 py-10 lg:px-8 lg:py-14"><PageIntro eyebrow="Keep in touch" title="Messages" body="The work gets better when the conversation stays open." action={<Button onClick={() => setNewMessageOpen(true)}><Plus size={16} /> New message</Button>} /><div className="mt-9 grid min-h-[600px] overflow-hidden rounded-2xl border border-border bg-card lg:grid-cols-[320px_1fr]"><aside className="border-b border-border lg:border-b-0 lg:border-r"><div className="flex items-center justify-between border-b border-border p-4"><span className="font-display font-bold">Inbox <span className="ml-1 rounded-md bg-[#f3d9d3] px-1.5 py-0.5 font-mono text-[10px] text-accent">2</span></span><button onClick={() => setNewMessageOpen(true)} className="focus-ring grid size-8 place-items-center rounded-lg text-muted-foreground hover:bg-muted" aria-label="Start a new message"><Plus size={17} /></button></div><div className="p-3">{conversations.map((conversation) => <button key={conversation.id} onClick={() => setSelectedId(conversation.id)} className={`flex w-full items-center gap-3 rounded-xl p-3 text-left transition ${selected.id === conversation.id ? 'bg-muted' : 'hover:bg-muted/60'}`} aria-pressed={selected.id === conversation.id}><Avatar person={{ initials: conversation.initials, accent: conversation.accent }} size="sm" /><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2"><b className="truncate text-sm">{conversation.name}</b><span className="shrink-0 font-mono text-[9px] text-muted-foreground">{conversation.time}</span></span><span className="mt-1 block truncate text-xs text-muted-foreground">{conversation.preview}</span></span>{conversation.unread > 0 && <span className="grid size-5 place-items-center rounded-full bg-accent font-mono text-[9px] text-accent-foreground">{conversation.unread}</span>}</button>)}</div></aside><section className="flex min-h-[520px] flex-col"><div className="flex items-center justify-between border-b border-border p-4"><div className="flex items-center gap-3"><Avatar person={{ initials: selected.initials, accent: selected.accent }} size="sm" /><div><p className="text-sm font-bold">{selected.name}</p><p className="text-xs text-primary">{selected.role}</p></div></div><button onClick={() => setOptionsOpen(!optionsOpen)} className="focus-ring grid size-9 place-items-center rounded-lg text-muted-foreground hover:bg-muted" aria-label="Open message options" aria-expanded={optionsOpen}><MoreHorizontal size={18} /></button></div>{optionsOpen && <div className="border-b border-border bg-muted/50 px-5 py-3 text-xs text-muted-foreground"><button onClick={() => { setOptionsOpen(false); setSelectedId(conversations[0].id); }} className="font-semibold hover:text-primary">Mark conversation as read</button><span className="mx-3 text-border">·</span><button onClick={() => setOptionsOpen(false)} className="font-semibold hover:text-primary">Mute notifications</button></div>}<div className="flex-1 space-y-5 overflow-auto p-5 md:p-8"><div className="mx-auto max-w-[500px] text-center"><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Tuesday, June 18</span></div><div className="flex gap-3"><Avatar person={{ initials: selected.initials, accent: selected.accent }} size="sm" /><div className="max-w-[480px] rounded-2xl rounded-tl-sm bg-muted p-4 text-sm leading-6">Hey Muhammad Emmaduddin — I added a thought on the onboarding flow. The moment after the first successful transfer feels like a great place to give people confidence.</div></div><div className="ml-auto max-w-[430px] rounded-2xl rounded-tr-sm bg-primary p-4 text-sm leading-6 text-primary-foreground">Love that direction. I’ll fold it into the next pass and share a prototype this afternoon.</div>{(messagesByConversation[selected.id] ?? []).map((item, index) => <div key={`${item}-${index}`} className="ml-auto max-w-[430px] rounded-2xl rounded-tr-sm bg-primary p-4 text-sm leading-6 text-primary-foreground">{item}</div>)}{attachment && <div className="ml-auto max-w-[240px] rounded-xl border border-dashed border-primary bg-[#d8eee6] p-3 text-xs font-semibold text-[#176354]">work-sample.pdf attached</div>}</div><form onSubmit={sendMessage} className="border-t border-border p-4"><div className="flex items-end gap-2 rounded-xl border border-border bg-background p-2 focus-within:border-primary"><button type="button" onClick={() => setAttachment(!attachment)} className={`focus-ring grid size-9 place-items-center rounded-lg ${attachment ? 'bg-[#d8eee6] text-primary' : 'text-muted-foreground hover:bg-muted'}`} aria-label="Attach a work sample" aria-pressed={attachment}><Paperclip size={17} /></button><textarea value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Write a thoughtful reply..." rows={1} className="max-h-24 min-h-9 flex-1 resize-none bg-transparent px-2 py-2 text-sm outline-none placeholder:text-muted-foreground" aria-label="Message text" /><button type="submit" className="focus-ring grid size-9 place-items-center rounded-lg bg-primary text-primary-foreground transition hover:shadow-md disabled:opacity-50" disabled={!message.trim()} aria-label="Send message"><Send size={16} /></button></div></form></section></div></main>{newMessageOpen && <Modal title="Start a new conversation" onClose={() => setNewMessageOpen(false)}><form onSubmit={startConversation} className="grid gap-5"><p className="text-sm leading-6 text-muted-foreground">Keep the first note specific and generous. A little context goes a long way.</p><label className="grid gap-2"><span className="text-sm font-bold">Who would you like to message?</span><input value={newRecipient} onChange={(event) => setNewRecipient(event.target.value)} placeholder="Name or company" className="h-11 rounded-xl border border-border bg-card px-3 text-sm outline-none focus:border-primary" required /></label><div className="flex justify-end gap-3"><Button variant="outline" onClick={() => setNewMessageOpen(false)}>Cancel</Button><Button type="submit">Create conversation <ArrowRight size={16} /></Button></div></form></Modal>}</Shell>;
}

function NotificationsPage() {
  const [items, setItems] = usePersistentState<Notification[]>('workforge-notifications', seedNotifications);
  const unread = items.filter((item) => item.unread).length;
  const markAll = () => setItems(items.map((item) => ({ ...item, unread: false })));
  const icons: Record<Notification['type'], ReactNode> = { proposal: <FileText size={17} />, message: <MessageCircle size={17} />, recommendation: <Sparkles size={17} />, shortlist: <Star size={17} />, project: <BriefcaseBusiness size={17} />, deadline: <Clock3 size={17} />, profile: <UserRound size={17} /> };
  return <Shell><main className="page-in mx-auto max-w-[900px] px-5 py-10 lg:px-8 lg:py-14"><PageIntro eyebrow="Stay in the loop" title="Notifications" body={`${unread ? `${unread} things worth a look.` : 'You are all caught up.'} Your updates live here.`} action={unread > 0 ? <Button variant="outline" onClick={markAll}>Mark all as read</Button> : undefined} /><div className="mt-9 grid gap-3">{items.length ? items.map((item) => <Link key={item.id} href={item.href} onClick={() => setItems(items.map((current) => current.id === item.id ? { ...current, unread: false } : current))} className={`flex gap-4 rounded-2xl border border-border p-5 transition hover:-translate-y-0.5 hover:shadow-soft ${item.unread ? 'bg-card' : 'bg-background'}`}><span className={`grid size-10 shrink-0 place-items-center rounded-xl ${item.unread ? 'bg-[#d8eee6] text-primary' : 'bg-muted text-muted-foreground'}`}>{icons[item.type]}</span><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center justify-between gap-2"><b className="text-sm">{item.title}</b><span className="font-mono text-[10px] text-muted-foreground">{item.time}</span></span><span className="mt-1 block text-sm leading-6 text-muted-foreground">{item.body}</span></span>{item.unread && <span className="mt-2 size-2 shrink-0 rounded-full bg-accent" aria-label="Unread" />}</Link>) : <EmptyState title="A quiet inbox" body="When there is something worth your attention, it will show up here." />}</div></main></Shell>;
}

function PostJob() {
  const [submitted, setSubmitted] = useState(false);
  const [values, setValues] = useState({ title: '', details: '', category: 'Design & Creative', skills: '', budget: '$2,000 – $5,000', budgetType: 'Fixed project', experience: 'Mid-level', timeline: '4–6 weeks', jobType: 'Project' });
  const [error, setError] = useState('');
  const update = (key: keyof typeof values, value: string) => setValues((current) => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => { event.preventDefault(); if (values.title.trim().length < 8) return setError('Give the project a specific title so the right people can find it.'); if (values.details.trim().length < 40) return setError('Add more context about the work and what a great outcome looks like.'); if (!values.skills.trim()) return setError('Add at least one skill so independent professionals can understand the fit.'); setError(''); setSubmitted(true); };
  if (submitted) return <Shell><main className="page-in mx-auto max-w-[760px] px-5 py-20 lg:py-28 text-center"><span className="mx-auto grid size-16 place-items-center rounded-[22px] bg-[#d8eee6] text-primary"><Check size={30} /></span><p className="mt-7 font-mono text-[10px] uppercase tracking-[.18em] text-primary">Your local preview</p><h1 className="mt-4 font-display text-5xl font-bold tracking-[-.07em]">Your brief is ready.</h1><p className="mx-auto mt-5 max-w-[500px] text-lg leading-8 text-muted-foreground">This frontend preview has captured the information you entered without pretending it is permanently stored on a server.</p><div className="mt-8 rounded-2xl border border-border bg-card p-5 text-left"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-primary">{values.category} · {values.jobType}</p><h2 className="mt-3 font-display text-2xl font-bold">{values.title}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{values.details}</p><div className="mt-4 flex flex-wrap gap-2">{values.skills.split(',').map((skill) => skill.trim()).filter(Boolean).map((skill) => <Badge key={skill}>{skill}</Badge>)}</div><div className="mt-5 grid gap-3 sm:grid-cols-3"><InfoRow label="Budget" value={`${values.budget} · ${values.budgetType}`} /><InfoRow label="Experience" value={values.experience} /><InfoRow label="Timeline" value={values.timeline} /></div></div><div className="mt-9 flex flex-wrap justify-center gap-3"><Link href="/dashboard/client" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-5 text-sm font-bold text-primary-foreground">Open client workspace <ArrowRight size={16} /></Link><Button variant="outline" onClick={() => { setSubmitted(false); setValues({ title: '', details: '', category: 'Design & Creative', skills: '', budget: '$2,000 – $5,000', budgetType: 'Fixed project', experience: 'Mid-level', timeline: '4–6 weeks', jobType: 'Project' }); }}>Post another</Button></div></main></Shell>;
  return <Shell><main className="page-in mx-auto max-w-[980px] px-5 py-10 lg:px-8 lg:py-14"><Link href="/dashboard/client" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowLeft size={16} /> Back to workspace</Link><div className="mt-9 grid gap-10 lg:grid-cols-[1fr_300px]"><div><PageIntro eyebrow="Start a new collaboration" title={<>Tell the good people<br />what you’re building.</>} body="The clearer your brief, the better the conversation. You can always edit the details later." />{error && <div className="mt-6"><ErrorState title="A little more context, please" body={error} /></div>}<form onSubmit={submit} className="mt-10 grid gap-6"><label className="grid gap-2"><span className="text-sm font-bold">Project title</span><input value={values.title} onChange={(event) => update('title', event.target.value)} required placeholder="e.g. Product designer for a new health experience" className="h-12 rounded-xl border border-border bg-card px-4 text-sm outline-none transition focus:border-primary" /></label><label className="grid gap-2"><span className="text-sm font-bold">What do you need help with?</span><textarea value={values.details} onChange={(event) => update('details', event.target.value)} required rows={7} placeholder="Share the context, the shape of the work, and what a great outcome looks like..." className="resize-none rounded-xl border border-border bg-card p-4 text-sm leading-6 outline-none transition focus:border-primary" /></label><div className="grid gap-5 sm:grid-cols-2"><FilterSelect label="Category" value={values.category} onChange={(value) => update('category', value)} options={categories.map((item) => item.name)} /><label className="grid gap-1.5"><span className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">Skills</span><input value={values.skills} onChange={(event) => update('skills', event.target.value)} placeholder="React, Figma, user research" className="h-11 rounded-xl border border-border bg-card px-3 text-sm outline-none focus:border-primary" /><span className="text-xs text-muted-foreground">Separate skills with commas.</span></label><FilterSelect label="Budget" value={values.budget} onChange={(value) => update('budget', value)} options={['$2,000 – $5,000', '$5,000 – $10,000', '$10,000+', '$65 – $100 / hr']} /><FilterSelect label="Budget type" value={values.budgetType} onChange={(value) => update('budgetType', value)} options={['Fixed project', 'Hourly engagement']} /><FilterSelect label="Experience" value={values.experience} onChange={(value) => update('experience', value)} options={['Entry level', 'Mid-level', 'Senior']} /><FilterSelect label="Timeline" value={values.timeline} onChange={(value) => update('timeline', value)} options={['1–2 weeks', '4–6 weeks', '6–8 weeks', '3+ months']} /><FilterSelect label="Job type" value={values.jobType} onChange={(value) => update('jobType', value)} options={['Project', 'Ongoing']} /></div><Button type="submit" className="mt-2 w-fit px-6">Preview project <ArrowRight size={16} /></Button></form></div><aside className="h-fit rounded-2xl bg-[#f5e6bf] p-6"><Sparkles size={20} className="text-[#765a19]" /><h2 className="mt-5 font-display text-xl font-bold tracking-[-.03em]">A note on good briefs</h2><p className="mt-3 text-sm leading-6 text-[#765a19]">The best projects give people a sense of why the work matters, not only what needs to be delivered.</p><div className="mt-5 border-t border-[#d8c798] pt-4 text-xs leading-5 text-[#765a19]"><b>Try including:</b><br />• What success looks like<br />• Who you’ll work with<br />• Your ideal timeline</div></aside></div></main></Shell>;
}

function SettingsPage() {
  const [tab, setTab] = useState<'profile' | 'notifications' | 'security' | 'preferences'>('profile');
  const [saved, setSaved] = useState(false);
  const [email, setEmail] = useState(true);
  const [dark, setDark] = useState(false);
  const [notice, setNotice] = useState('');
  const tabs = [{ id: 'profile', label: 'Profile & account' }, { id: 'notifications', label: 'Notifications' }, { id: 'security', label: 'Security' }, { id: 'preferences', label: 'Preferences' }] as const;
  const save = () => { setSaved(true); setNotice('Your local settings have been saved for this preview.'); window.setTimeout(() => setSaved(false), 1800); };
  return <Shell><main className="page-in mx-auto max-w-[1000px] px-5 py-10 lg:px-8 lg:py-14"><PageIntro eyebrow="Your account" title="Settings" body="Small adjustments, exactly where you need them." />{notice && <div className="mt-6"><Notice onClose={() => setNotice('')}>{notice}</Notice></div>}<div className="mt-9 grid gap-8 md:grid-cols-[210px_1fr]"><aside className="flex gap-1 overflow-auto md:grid md:content-start" role="tablist" aria-label="Settings sections">{tabs.map((item) => <button key={item.id} role="tab" aria-selected={tab === item.id} onClick={() => setTab(item.id)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-left text-sm font-semibold ${tab === item.id ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`}>{item.label}</button>)}</aside><div className="grid gap-5">{tab === 'profile' && <section className="rounded-2xl border border-border bg-card p-5 md:p-7"><div className="flex items-center justify-between border-b border-border pb-5"><div><h2 className="font-display text-xl font-bold">Profile details</h2><p className="mt-1 text-sm text-muted-foreground">This is how people see you around WorkForge.</p></div><Avatar person={{ initials: 'AM', accent: 'bg-[#d7efe7]' }} /></div><div className="mt-6 grid gap-5 sm:grid-cols-2"><label className="grid gap-2"><span className="text-sm font-bold">Full name</span><input defaultValue="Muhammad Emmaduddin" className="h-11 rounded-xl border border-border bg-background px-3 text-sm outline-none focus:border-primary" /></label><label className="grid gap-2"><span className="text-sm font-bold">Title</span><input defaultValue="Independent product designer" className="h-11 rounded-xl border border-border bg-background px-3 text-sm outline-none focus:border-primary" /></label><label className="grid gap-2 sm:col-span-2"><span className="text-sm font-bold">Bio</span><textarea defaultValue="I help thoughtful teams make clear, useful products." rows={4} className="resize-none rounded-xl border border-border bg-background p-3 text-sm leading-6 outline-none focus:border-primary" /></label></div><div className="mt-6 flex justify-end"><Button onClick={save}>{saved ? <><Check size={16} /> Saved</> : 'Save changes'}</Button></div></section>}{tab === 'notifications' && <section className="rounded-2xl border border-border bg-card p-5 md:p-7"><h2 className="font-display text-xl font-bold">Notification preferences</h2><p className="mt-1 text-sm text-muted-foreground">Choose what is worth interrupting your day for.</p>{[['Weekly opportunities', 'A considered selection based on your skills.'], ['New proposals and shortlists', 'Know when a project moves forward.'], ['Messages and project updates', 'Stay close to the work that is already moving.']].map(([title, body], index) => <div className="mt-6 flex items-center justify-between border-t border-border pt-5" key={title}><div><p className="text-sm font-bold">{title}</p><p className="mt-1 text-xs text-muted-foreground">{body}</p></div><button onClick={() => setEmail(!email)} className={`relative h-6 w-11 rounded-full transition ${email || index !== 0 ? 'bg-primary' : 'bg-muted'}`} aria-label={`Toggle ${title}`} aria-pressed={email || index !== 0}><span className={`absolute top-1 size-4 rounded-full bg-card transition-all ${email || index !== 0 ? 'left-6' : 'left-1'}`} /></button></div>)}</section>}{tab === 'security' && <section className="rounded-2xl border border-border bg-card p-5 md:p-7"><div className="flex items-start gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[#d8eee6] text-primary"><LockKeyhole size={18} /></span><div><h2 className="font-display text-xl font-bold">Security preview</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Authentication and account recovery are intentionally represented as frontend-only states in this MVP.</p></div></div><div className="mt-6 grid gap-3"><div className="flex items-center justify-between rounded-xl bg-muted/60 p-4"><span className="text-sm font-semibold">Email verification</span><Badge tone="gold">Preview only</Badge></div><div className="flex items-center justify-between rounded-xl bg-muted/60 p-4"><span className="text-sm font-semibold">Two-step sign in</span><Badge tone="gold">Coming later</Badge></div></div></section>}{tab === 'preferences' && <section className="rounded-2xl border border-border bg-card p-5 md:p-7"><h2 className="font-display text-xl font-bold">Workspace preferences</h2><p className="mt-1 text-sm text-muted-foreground">Tune the way WorkForge feels while you work.</p><div className="mt-6 flex items-center justify-between border-t border-border pt-5"><div><p className="text-sm font-bold">Use dark workspace preview</p><p className="mt-1 text-xs text-muted-foreground">The dark tokens are ready for a future full theme.</p></div><button onClick={() => setDark(!dark)} className={`relative h-6 w-11 rounded-full transition ${dark ? 'bg-primary' : 'bg-muted'}`} aria-label="Toggle dark workspace preview" aria-pressed={dark}><span className={`absolute top-1 size-4 rounded-full bg-card transition-all ${dark ? 'left-6' : 'left-1'}`} /></button></div><div className="mt-5 rounded-xl bg-muted/60 p-4 text-sm leading-6 text-muted-foreground">{dark ? 'Dark preview preference saved locally. Full theme application is intentionally deferred.' : 'WorkForge is using its warm paper workspace.'}</div><div className="mt-6 flex justify-end"><Button onClick={save}>{saved ? 'Saved' : 'Save preferences'}</Button></div></section>}</div></div></main></Shell>;
}

function Auth({ signup = false }: { signup?: boolean }) {
  const [submitted, setSubmitted] = useState(false);
  const [notice, setNotice] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); setSubmitted(true); };
  return <div className="noise grid min-h-[100dvh] bg-[#f2eadb] lg:grid-cols-[.85fr_1.15fr]"><div className="hidden flex-col justify-between bg-[#23303c] p-10 text-[#f1eadf] lg:flex"><Link href="/"><span className="font-display text-lg font-bold">work<span className="text-secondary">forge</span></span></Link><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#9db2aa]">A place for good work</p><h1 className="mt-5 max-w-[470px] font-display text-6xl font-bold leading-[.94] tracking-[-.07em]">Come for the work.<br /><span className="text-secondary">Stay for the people.</span></h1><p className="mt-7 max-w-[380px] text-base leading-7 text-[#adbbb6]">WorkForge is a quieter kind of marketplace — built around trust, context, and the joy of making things well.</p></div><p className="font-mono text-[10px] uppercase tracking-[.15em] text-[#778c86]">Independent by design.</p></div><main className="flex items-center justify-center p-5 py-12"><div className="w-full max-w-[430px]"><div className="mb-10 lg:hidden"><Link href="/" className="font-display text-lg font-bold">work<span className="text-secondary">forge</span></Link></div><Link href="/" className="mb-10 hidden items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary lg:inline-flex"><ArrowLeft size={16} /> Back to WorkForge</Link>{notice && <div className="mb-6"><Notice tone="gold" onClose={() => setNotice('')}>{notice}</Notice></div>}{submitted ? <div className="text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-[#d8eee6] text-primary"><Check size={27} /></span><h2 className="mt-6 font-display text-3xl font-bold tracking-[-.05em]">{signup ? 'You’re on your way.' : 'Preview step complete.'}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{signup ? 'Your frontend demo account is ready. Take a look around and find your next good collaboration.' : 'This prototype has accepted the form locally. Real authentication is intentionally not connected yet.'}</p><Link href={signup ? '/dashboard/freelancer' : '/'} className="mt-7 inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-5 text-sm font-bold text-primary-foreground">Continue <ArrowRight size={16} /></Link></div> : <><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">{signup ? 'Join the community' : 'Welcome back'}</p><h2 className="mt-3 font-display text-4xl font-bold tracking-[-.06em]">{signup ? 'Make your next move.' : 'Good to see you again.'}</h2><p className="mt-3 text-muted-foreground">{signup ? 'A better place to find work that matters.' : 'Pick up where you left off.'}</p><form onSubmit={submit} className="mt-9 grid gap-5"><label className="grid gap-2"><span className="text-sm font-bold">Email address</span><input type="email" required placeholder="you@company.com" className="h-12 rounded-xl border border-border bg-card px-4 text-sm outline-none focus:border-primary" /></label>{signup && <label className="grid gap-2"><span className="text-sm font-bold">Your full name</span><input required placeholder="Muhammad Emmaduddin" className="h-12 rounded-xl border border-border bg-card px-4 text-sm outline-none focus:border-primary" /></label>}<label className="grid gap-2"><div className="flex items-center justify-between"><span className="text-sm font-bold">Password</span>{!signup && <button type="button" onClick={() => setNotice('Password recovery is represented locally in this frontend MVP.')} className="text-xs font-semibold text-primary">Forgot password?</button>}</div><input type="password" required placeholder="At least 8 characters" className="h-12 rounded-xl border border-border bg-card px-4 text-sm outline-none focus:border-primary" /></label><Button type="submit" className="mt-2 w-full">{signup ? 'Create your account' : 'Log in'} <ArrowRight size={16} /></Button></form><div className="my-7 flex items-center gap-3 text-xs text-muted-foreground"><span className="h-px flex-1 bg-border" /> or <span className="h-px flex-1 bg-border" /></div><button onClick={() => setNotice('Google sign-in is intentionally a frontend-only placeholder for this MVP.')} className="flex h-11 w-full items-center justify-center gap-2 rounded-xl border border-border bg-card text-sm font-semibold hover:border-primary"><span className="font-display text-lg font-bold text-accent">G</span> Continue with Google</button><p className="mt-7 text-center text-sm text-muted-foreground">{signup ? 'Already have an account?' : 'New to WorkForge?'} <Link href={signup ? '/login' : '/signup'} className="font-bold text-primary">{signup ? 'Log in' : 'Create an account'}</Link></p></>}</div></main></div>;
}

function InfoPage({ kind }: { kind: 'about' | 'help' | 'terms' | 'privacy' }) {
  const content = { about: ['A better place to begin', 'WorkForge is a thoughtful marketplace for independent professionals and the teams who know the difference.', 'We believe trust starts with context: clearer briefs, profiles with proof, and room for people to do their best work.'], help: ['How can we help?', 'Start with discovery, save promising work, and use messages to open a thoughtful conversation.', 'This help center is a frontend preview. Real support workflows will be connected after the product foundation is in place.'], terms: ['WorkForge terms', 'This prototype is for exploring the WorkForge experience.', 'Nothing in this frontend preview creates a real contract, payment obligation, employment relationship, or stored account.'], privacy: ['Your work, with care', 'This prototype stores a small amount of state in your browser so interactions feel real during exploration.', 'Real privacy, account, and data-retention policies will be added before production features are enabled.'] }[kind];
  return <Shell><main className="page-in mx-auto max-w-[800px] px-5 py-16 lg:px-8 lg:py-24"><Link href="/" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowLeft size={16} /> Back to WorkForge</Link><p className="mt-12 font-mono text-[10px] uppercase tracking-[.18em] text-primary">WorkForge · {kind}</p><h1 className="mt-4 font-display text-5xl font-bold tracking-[-.07em]">{content[0]}</h1><p className="mt-6 text-xl leading-8 text-muted-foreground">{content[1]}</p><div className="mt-10 rounded-2xl border border-border bg-card p-6 text-sm leading-7 text-muted-foreground"><p>{content[2]}</p></div></main></Shell>;
}

function NotFoundPage({ title = 'This page took an unexpected detour.', body = 'The route you followed is not available here, but there is still good work to find.' }: { title?: string; body?: string }) {
  return <Shell><main className="page-in mx-auto grid min-h-[70dvh] max-w-[760px] place-items-center px-5 py-20 text-center"><div><span className="mx-auto grid size-16 place-items-center rounded-[22px] bg-[#f3d9d3] text-accent"><CircleAlert size={30} /></span><p className="mt-7 font-mono text-[10px] uppercase tracking-[.18em] text-accent">A small detour</p><h1 className="mt-4 font-display text-5xl font-bold tracking-[-.07em]">{title}</h1><p className="mx-auto mt-5 max-w-[500px] text-lg leading-8 text-muted-foreground">{body}</p><div className="mt-9 flex flex-wrap justify-center gap-3"><Link href="/" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-5 text-sm font-bold text-primary-foreground">Go home <ArrowRight size={16} /></Link><Link href="/jobs" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-border bg-card px-5 text-sm font-bold">Find work <BriefcaseBusiness size={16} /></Link><Link href="/freelancers" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-border bg-card px-5 text-sm font-bold">Find talent <UsersRound size={16} /></Link></div></div></main></Shell>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch>
    <Route path="/" component={Home} />
    <Route path="/jobs" component={Jobs} />
    <Route path="/jobs/:id" component={JobDetail} />
    <Route path="/freelancers" component={Freelancers} />
    <Route path="/freelancers/:id" component={FreelancerProfile} />
    <Route path="/clients/:id" component={ClientProfile} />
    <Route path="/dashboard/freelancer"><Dashboard role="freelancer" /></Route>
    <Route path="/dashboard/client"><Dashboard role="client" /></Route>
    <Route path="/workspace"><Dashboard role="freelancer" /></Route>
    <Route path="/messages" component={Messages} />
    <Route path="/notifications" component={NotificationsPage} />
    <Route path="/post-job" component={PostJob} />
    <Route path="/login" component={() => <Auth />} />
    <Route path="/signup" component={() => <Auth signup />} />
    <Route path="/settings" component={SettingsPage} />
    <Route path="/about"><InfoPage kind="about" /></Route>
    <Route path="/help"><InfoPage kind="help" /></Route>
    <Route path="/terms"><InfoPage kind="terms" /></Route>
    <Route path="/privacy"><InfoPage kind="privacy" /></Route>
    <Route component={() => <NotFoundPage />} />
  </Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;